const stroke = (value: PackGlyphProps['strokeWidth']) =>
  typeof value === 'number' ? value : undefined

function huge(icon: IconSvgElement): PackGlyph {
  function HugeGlyph(props: PackGlyphProps) {
    return (
      <HugeiconsIcon
        aria-hidden={props['aria-hidden']}
        aria-label={props['aria-label']}
        className={props.className}
        color={props.color ?? 'currentColor'}
        icon={icon}
        onClick={props.onClick}
        size={props.size ?? 24}
        strokeWidth={stroke(props.strokeWidth)}
        style={props.style}
      />
    )
  }
  return HugeGlyph
}

function draw(icon: SvgIcon, mode: 'fill' | 'stroke'): PackGlyph {
  function SvgGlyph(props: PackGlyphProps) {
    const size = typeof props.size === 'number' ? props.size : 24
    return (
      <svg
        aria-hidden={props['aria-hidden']}
        aria-label={props['aria-label']}
        className={props.className}
        dangerouslySetInnerHTML={{ __html: icon.html }}
        fill={mode === 'fill' ? (props.color ?? 'currentColor') : 'none'}
        height={size}
        onClick={props.onClick}
        stroke={mode === 'stroke' ? (props.color ?? 'currentColor') : undefined}
        strokeLinecap={mode === 'stroke' ? 'round' : undefined}
        strokeLinejoin={mode === 'stroke' ? 'round' : undefined}
        strokeWidth={mode === 'stroke' ? (stroke(props.strokeWidth) ?? 2) : undefined}
        style={props.style}
        viewBox={icon.viewBox}
        width={size}
        xmlns="http://www.w3.org/2000/svg"
      />
    )
  }
  return SvgGlyph
}

